fn max(a: &Vec<i32>, n: usize) -> i32 {
    // Precondition assumptions (can be omitted if you're sure the caller
    // always upholds them)
    debug_assert!(n > 0, "n must be strictly greater than 0");
    debug_assert!(n <= a.len(), "n must not exceed the length of the array");
    debug_assert!(n < 1000, "n must be strictly less than 1000");

    // Initialize the maximum with the first element in the prefix
    let mut current_max = a[0];

    // Iterate over the rest of the prefix and update the maximum if needed
    for &value in &a[1..n] {
        if value > current_max {
            current_max = value;
        }
    }

    current_max
}

